/* Owner's mobile reading and process refinements, 2026-11-04. */
@media(max-width:899px){
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-wants-editorial {list-style:none;padding:0;margin:24px 0 38px;display:grid;gap:32px}
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-wants-editorial li {position:relative;width:88%;margin:0;padding:0 0 14px}
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-wants-editorial li:nth-child(even) {margin-left:auto;text-align:right}
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-wants-editorial p {font-family:var(--ff-display);font-size:1.75rem;line-height:1.2;font-weight:500;margin:0;text-wrap:balance;color:var(--m-text)}
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-want-line {position:absolute;left:calc(-1 * var(--m-gutter));right:0;bottom:0;height:11px;color:#a55c4b;pointer-events:none;overflow:hidden}
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-wants-editorial li:nth-child(even) .preview-want-line {left:0;right:calc(-1 * var(--m-gutter))}
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-want-line svg.terrain-art {display:block;width:100%;height:100%;color:#a55c4b}
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-process-steps > li:last-child {text-align:center}
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-process-steps > li:last-child h3 {display:block;text-wrap:balance}
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-process-steps > li:last-child .preview-step-number {margin-right:12px}
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-process-steps > li:last-child .preview-step-title {display:inline;max-width:none}
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-process-steps > li:last-child p {margin-left:0}
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-process-steps .preview-curve-arrow {right:auto;bottom:auto;transform:none;opacity:0;transition:opacity 400ms cubic-bezier(.23,1,.32,1);overflow:visible}
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-process-steps .preview-curve-arrow.is-visible {opacity:1}
}
@media(prefers-reduced-motion:reduce){
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-process-steps .preview-curve-arrow {opacity:1;transition:none}
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-want-line {clip-path:none!important}
}
